head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
scwin.vScrenID = 'ULDSTF15845.xml'; // 화면명

scwin.xSize = 350; // 상세팝업 x좌표
scwin.ySize = 100; // 상세팝업 y좌표
scwin.popWidth = 1287; // 상세팝업 가로 사이즈
scwin.popHeight = 670;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 상세팝업 세로 사이즈

scwin.initPage = function() {
    scwin.fn_SetYear();
};
scwin.fn_SetYear = function() {
    // 화면 진입 후 연도 조회 중일때 selectbox에 빈칸으로 보여서 '조회중' 이라는 문구를 넣음
    // ^temp 에서 temp는 의미 없는 값이지만, ^뒤에 데이타가 있어야 문구가 노출됨.
    cmb_YearList.CBData = "연도 조회중...^temp";
    // 연도조회(데이타가 등록 되어 있다면 연도가 조회 될 것이고 등록 안되어 있다면 연도가 없음)
    dts_year.DataID = "/EsgSearch.do?method=getYearList";
    dts_year.Reset();
};
scwin.fn_Search = function() {
    // 선택 된 연도
    var year = $c.cp.valueOfIndex(cmb_YearList, "YEAR", cmb_YearList.getSelectedIndex());
    if (year == '') {
        $c.win.alert("연도를 선택해주세요");
        return;
    }
    $c.cm.ShowWin(grd_Grid); // loading중 display

    // 핵심지표 준수현황표 조회
    var url = "/EsgSearch.do?method=coreIndicObrStat";
    url += "&YEAR=" + year; // 연도

    dts_Grid.DataID = url;
    dts_Grid.Reset();
};
scwin.fn_Excel = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    // 선택한 연도(파일명에 선택한 년도를 붙임)
    var year = $c.cp.valueOfIndex(cmb_YearList, "YEAR", cmb_YearList.getSelectedIndex());
    //엑셀 다운로드
    $c.data.downloadGridViewOffice(grd_Grid, "핵심지표준수현황표", year + "년_핵심지표준수현황표.xlsx", 2 + 8, 0);
};


// 세부원칙별 상세조회 시 데이타 셋팅
scwin.fn_setData = function(dtsObj, row, colid) {
    // 핵심지표 준수현황
    if (dtlRoleSel == 'role0-3') {
        if (colid == "CORE_INDIC_COMP_DSC") {
            reqElmtId = "krx-cg_ComplianceStatusWithKeyIndicatorsOfCorporateGovernanceExplanatory";
        }
    }

    // 접수번호,  엘리먼트 아이디를 조합하여 데이타를 넘긴다.
    data = dtsObj.getCellData(eval(row), 'ACPT_NO') + "^" + reqElmtId;
};
scwin.openPopup = async function() {
    // 상세조회 팝업
    await $c.frame.CreateDialogFrame("gform", "/esg/esg_viewer.gfm", "세부원칙 상세조회", scwin.xSize, scwin.ySize, scwin.popWidth, scwin.popHeight, "window");
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1); // 검색조건 패널에 스타일 적용
    scwin.initPage();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Grid); //조회완료시 LOADING 이미지 종료
    //FillGridHeaderTotalCnt(rowcount, panel_page);	//총 건수

};
scwin.dts_year_OnLoadCompleted = function(rowcount) {
    // 연도가 없다는건 실제 데이타가 없다는 것이기 때문에 별도 텍스트를 보여줌
    if (rowcount == 0) {
        dts_year.insertRow();
        dts_year.setCellData(1, "YEAR_TEXT", '연도가 존재하지 않습니다');
        dts_year.setCellData(1, "YEAR", '');
    }
};
scwin.btn_Excel_onclick = function() {
    scwin.fn_Excel();
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    // 기업지배구조핵심지표준수현황 상세조회
    // 클릭해야 되는 컬럼이 아닐 경우는 스킵
    if (colid != "CORE_INDIC_COMP_DSC" && colid != "DISCLS_PUBL_DDTM") {
        return;
    }
    // row가 0번째일 경우 스킵(타이틀을 클릭할때)
    if (row == 0) {
        return;
    }
    // 데이타가 없을 경우는 스킵
    if (colid == "CORE_INDIC_COMP_DSC") {
        if (dts_Grid.getCellData(eval(row), 'CORE_INDIC_COMP_DSC') == '') {
            return;
        }
    }
    if (colid == "DISCLS_PUBL_DDTM") {
        // 공시시각을 클릭할 경우 공시뷰어 메인창을 오픈
        var gAcptNo = dts_Grid.getCellData(eval(row), "ACPT_NO"); // 접수번호
        $c.stf.fn_OpenDisclViewer(gAcptNo, "R");
    } else {
        dtlRoleSel = 'role0-3';
        scwin.fn_setData(dts_Grid, row, colid);
        scwin.openPopup();
    }
};
